int TextEditor::characterAt(Point<float>point){const auto box=textArea();int begin=0,end=text_.length();if(multiline_){layoutText();const auto row=std::clamp(int((point.y-box.getY()+yOffset_)/(font_.getHeight()*1.4f)),0,int(lines_.size())-1);begin=lines_[std::size_t(row)].begin;end=lines_[std::size_t(row)].end;}const auto start=begin;const float x=point.x-box.getX();while(begin<end){const int middle=begin+(end-begin)/2;const auto width=font_.getStringWidthFloat(text_.substring(start,middle+1));if(width<x)begin=middle+1;else end=middle;}return begin;}
void TextEditor::mouseDown(const MouseEvent&e){if(!e.mods.isLeftButtonDown())return;grabKeyboardFocus();if(multiline_&&scrollbars_&&e.position.x>=textArea().getRight()){scrollDragging_=true;mouseDrag(e);return;}selecting_=true;if(e.getNumberOfClicks()>1){selectAll();return;}const auto next=characterAt(e.position);if(!e.mods.isShiftDown())selectionStart_=next;selectionEnd_=caret_=next;repaint();}
void TextEditor::mouseDrag(const MouseEvent&e){if(scrollDragging_){layoutText();const auto box=textArea();const float total=float(lines_.size())*font_.getHeight()*1.4f;yOffset_=std::clamp((e.position.y-box.getY())/std::max(1.f,box.getHeight()),0.f,1.f)*std::max(0.f,total-box.getHeight());}else if(selecting_)selectionEnd_=caret_=characterAt(e.position);repaint();}
