void Slider::setRange(double minimum,double maximum,double interval){if(!std::isfinite(minimum)||!std::isfinite(maximum)||maximum<=minimum||!std::isfinite(interval)||interval<0)throw std::invalid_argument("Invalid native slider range");minimum_=minimum;maximum_=maximum;interval_=interval;setValue(value_,dontSendNotification);updateText();repaint();}
